<?php
/**
 * Regenerates includes/icons-data.php from Lucide SVG files.
 *
 * Usage: php bin/build-icons.php <lucide-tag> <dir-with-svg-files> && composer run phpcbf
 * (phpcbf applies WordPress Coding Standards formatting to the generated file.)
 * Icons: Lucide (https://lucide.dev), ISC License. Only element names and
 * geometry attributes are kept; everything is escaped again at render time.
 *
 * @package BeeMonitor
 */

if ( PHP_SAPI !== 'cli' || $argc < 3 ) {
	fwrite( STDERR, "Usage: php bin/build-icons.php <lucide-tag> <svg-dir>\n" );
	exit( 1 );
}
$tag     = $argv[1];
$dir     = rtrim( $argv[2], '/' );
$allowed = array(
	'path'    => array( 'd' ),
	'circle'  => array( 'cx', 'cy', 'r' ),
	'rect'    => array( 'x', 'y', 'width', 'height', 'rx', 'ry' ),
	'line'    => array( 'x1', 'y1', 'x2', 'y2' ),
	'ellipse' => array( 'cx', 'cy', 'rx', 'ry' ),
);
$icons   = array();
foreach ( glob( $dir . '/*.svg' ) as $file ) {
	$doc = new DOMDocument();
	if ( ! $doc->load( $file, LIBXML_NONET ) ) {
		fwrite( STDERR, "Skipping unreadable $file\n" );
		continue;
	}
	$shapes = array();
	foreach ( $doc->documentElement->childNodes as $node ) {
		if ( XML_ELEMENT_NODE !== $node->nodeType ) {
			continue;
		}
		if ( ! isset( $allowed[ $node->nodeName ] ) ) {
			fwrite( STDERR, "Unsupported element {$node->nodeName} in $file\n" );
			exit( 1 );
		}
		$attrs = array();
		foreach ( $allowed[ $node->nodeName ] as $attr ) {
			if ( $node->hasAttribute( $attr ) ) {
				$value = $node->getAttribute( $attr );
				if ( ! preg_match( '/^[0-9a-zA-Z .,\-]+$/', $value ) ) {
					fwrite( STDERR, "Unexpected value in $file\n" );
					exit( 1 );
				}
				$attrs[ $attr ] = $value;
			}
		}
		$shapes[] = array( $node->nodeName, $attrs );
	}
	$icons[ basename( $file, '.svg' ) ] = $shapes;
}
ksort( $icons );
$out = "<?php\n/**\n * Icon geometry generated by bin/build-icons.php from Lucide {$tag} (https://lucide.dev).\n * Lucide is licensed under the ISC License; see assets/icons/LICENSE-lucide.txt.\n * Do not edit by hand.\n *\n * @package BeeMonitor\n */\n\ndefined( 'ABSPATH' ) || exit;\n\nreturn " . var_export( $icons, true ) . ";\n";
file_put_contents( __DIR__ . '/../includes/icons-data.php', $out );
echo count( $icons ) . " icons written\n";
